<div class="dashboard-page-head"><div><p class="eyebrow">AI trading category</p><h1>Edit <?= e($category['name']) ?></h1><p class="muted">Updates affect future purchases only. Existing purchases retain their snapshots.</p></div><a class="button button-secondary" href="<?= e(route('admin.ai-trading')) ?>">Back</a></div>
